<?php
declare(strict_types=1);
require_once $_SERVER['DOCUMENT_ROOT'] . '/cnrbyte/vendors/branches/shifts/staff/branches.forms.php';
function cnr_hr_staff_options(mysqli $conn, int $vendorId): string {
    $html=''; $stmt=$conn->prepare('SELECT id,first_names,last_name FROM staff WHERE vendor_id=? ORDER BY last_name,first_names');$stmt->bind_param('i',$vendorId);$stmt->execute();$res=$stmt->get_result();
    while($r=$res->fetch_assoc())$html.='<option value="'.(int)$r['id'].'">'.cnr_h($r['first_names'].' '.$r['last_name']).'</option>';
    $stmt->close(); return $html;
}
function show_shift_roster_table(mysqli $conn): void {
    $v=(int)($_SESSION['vendor_info']['id']??0);$stmt=$conn->prepare('SELECT r.day_date,r.shift_name,r.day_name,r.time_of_day,r.shift_status,b.branch_name FROM roster r LEFT JOIN branches b ON b.id=r.branch_id WHERE r.vendor_id=? AND (r.staff_id IS NULL OR r.staff_id=0) ORDER BY r.day_date DESC LIMIT 100');$stmt->bind_param('i',$v);$stmt->execute();$res=$stmt->get_result();
    echo '<section class="cnr-form-card"><h3>Shift roster</h3><div class="cnr-table-wrap"><table><thead><tr><th>Date</th><th>Branch</th><th>Shift</th><th>Day</th><th>Time</th><th>Status</th></tr></thead><tbody>';
    while($r=$res->fetch_assoc())echo '<tr><td>'.cnr_h($r['day_date']).'</td><td>'.cnr_h($r['branch_name']).'</td><td>'.cnr_h($r['shift_name']).'</td><td>'.cnr_h($r['day_name']).'</td><td>'.cnr_h($r['time_of_day']).'</td><td>'.cnr_h($r['shift_status']).'</td></tr>';
    echo '</tbody></table></div></section>'; $stmt->close();
}
function show_staff_roster_table(mysqli $conn): void {
    $v=(int)($_SESSION['vendor_info']['id']??0);$stmt=$conn->prepare('SELECT r.day_date,r.shift_name,r.day_name,r.time_of_day,r.shift_status,s.first_names,s.last_name,b.branch_name FROM roster r JOIN staff s ON s.id=r.staff_id AND s.vendor_id=r.vendor_id LEFT JOIN branches b ON b.id=r.branch_id WHERE r.vendor_id=? ORDER BY r.day_date DESC LIMIT 100');$stmt->bind_param('i',$v);$stmt->execute();$res=$stmt->get_result();
    echo '<section class="cnr-form-card"><h3>Staff roster</h3><div class="cnr-table-wrap"><table><thead><tr><th>Date</th><th>Staff member</th><th>Branch</th><th>Shift</th><th>Time</th><th>Status</th></tr></thead><tbody>';
    while($r=$res->fetch_assoc())echo '<tr><td>'.cnr_h($r['day_date']).'</td><td>'.cnr_h($r['first_names'].' '.$r['last_name']).'</td><td>'.cnr_h($r['branch_name']).'</td><td>'.cnr_h($r['shift_name']).'</td><td>'.cnr_h($r['time_of_day']).'</td><td>'.cnr_h($r['shift_status']).'</td></tr>';
    echo '</tbody></table></div></section>'; $stmt->close();
}
function show_staff_payslip_table(mysqli $conn): void {
    $v=(int)($_SESSION['vendor_info']['id']??0);$stmt=$conn->prepare('SELECT p.created_at,p.earnings,p.deductions,p.amount,s.first_names,s.last_name FROM staff_payslip p JOIN staff s ON s.id=p.staff_id AND s.vendor_id=p.vendor_id WHERE p.vendor_id=? ORDER BY p.created_at DESC LIMIT 100');$stmt->bind_param('i',$v);$stmt->execute();$res=$stmt->get_result();
    echo '<section class="cnr-form-card"><h3>Payroll records (summary)</h3><p>These are recorded payroll summaries, not a substitute for approved statutory payroll calculations or payslips.</p><div class="cnr-table-wrap"><table><thead><tr><th>Date</th><th>Staff member</th><th>Earnings</th><th>Deductions</th><th>Net</th></tr></thead><tbody>';
    while($r=$res->fetch_assoc())echo '<tr><td>'.cnr_h($r['created_at']).'</td><td>'.cnr_h($r['first_names'].' '.$r['last_name']).'</td><td>R'.number_format((float)$r['earnings'],2).'</td><td>R'.number_format((float)$r['deductions'],2).'</td><td>R'.number_format((float)$r['amount'],2).'</td></tr>';
    echo '</tbody></table></div></section>'; $stmt->close();
}
function create_shift_roster_form(mysqli $conn): void { cnr_hr_roster_form($conn, false); }
function create_staff_roster_form(mysqli $conn): void { cnr_hr_roster_form($conn, true); }
function cnr_hr_roster_form(mysqli $conn, bool $forStaff): void {
    $v=(int)($_SESSION['vendor_info']['id']??0); echo '<section class="cnr-form-card"><h3>'.($forStaff?'Schedule staff member':'Create shift roster').'</h3><form method="post" action="/cnrbyte/vendors/module_action.run.php">'.cnr_csrf_field_local().'<input type="hidden" name="action" value="create_roster"><input type="hidden" name="for_staff" value="'.($forStaff?'1':'0').'">';
    echo '<label>Branch<select name="branch_id" required><option value="">Select branch</option>'; $stmt=$conn->prepare('SELECT id,branch_name FROM branches WHERE vendor_id=? ORDER BY branch_name');$stmt->bind_param('i',$v);$stmt->execute();$res=$stmt->get_result();while($r=$res->fetch_assoc())echo '<option value="'.(int)$r['id'].'">'.cnr_h($r['branch_name']).'</option>';$stmt->close();echo '</select></label>';
    echo '<label>Shift<select name="shift_id" required><option value="">Select shift</option>'; $stmt=$conn->prepare('SELECT id,shift_name FROM shifts WHERE vendor_id=? ORDER BY shift_name');$stmt->bind_param('i',$v);$stmt->execute();$res=$stmt->get_result();while($r=$res->fetch_assoc())echo '<option value="'.(int)$r['id'].'">'.cnr_h($r['shift_name']).'</option>';$stmt->close();echo '</select></label>';
    if($forStaff)echo '<label>Staff member<select name="staff_id" required><option value="">Select staff</option>'.cnr_hr_staff_options($conn,$v).'</select></label>';
    echo '<label>Date<input type="date" name="day_date" required></label><label>Day name<select name="day_name" required><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option><option>Saturday</option><option>Sunday</option></select></label><label>Day type<select name="day_type" required><option value="normal">Normal</option><option value="public_holiday">Public holiday</option><option value="overtime">Overtime</option></select></label><label>Time category<select name="time_of_day" required><option value="day">Day</option><option value="night">Night</option></select></label><label>Status<select name="shift_status" required><option value="scheduled">Scheduled</option><option value="confirmed">Confirmed</option><option value="leave">Leave</option></select></label><label>Time in<input type="time" name="time_in" required></label><label>Time out<input type="time" name="time_out" required></label><label>Lunch starts<input type="time" name="lunch_in"></label><label>Lunch ends<input type="time" name="lunch_out"></label><button class="cnr-button">Save roster entry</button></form></section>';
}
function create_staff_leave_form(mysqli $conn): void {
    $v=(int)($_SESSION['vendor_info']['id']??0);echo '<section class="cnr-form-card"><h3>Record staff leave request</h3><form method="post" action="/cnrbyte/vendors/module_action.run.php">'.cnr_csrf_field_local().'<input type="hidden" name="action" value="create_leave"><label>Staff member<select name="staff_id" required><option value="">Select staff</option>'.cnr_hr_staff_options($conn,$v).'</select></label><label>Leave type<select name="leave_type" required><option value="">Select leave type</option>'.cnr_vendor_lookup_options($conn,$v,'leave_type').'</select></label><label>Start date<input type="date" name="start_date" required></label><label>End date<input type="date" name="end_date" required></label><label>Reason<textarea name="reason" maxlength="500"></textarea></label><button class="cnr-button">Submit leave request</button></form></section>';
}
function create_hr_rates(mysqli $conn): void {
    echo '<section class="cnr-form-card"><h3>Set hourly rate</h3><form method="post" action="/cnrbyte/vendors/module_action.run.php">'.cnr_csrf_field_local().'<input type="hidden" name="action" value="create_hr_rate"><label>Day<select name="day_name" required><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option><option>Saturday</option><option>Sunday</option></select></label><label>Day type<select name="day_type" required><option value="normal">Normal</option><option value="public_holiday">Public holiday</option><option value="overtime">Overtime</option></select></label><label>Time category<select name="time_of_day" required><option value="day">Day</option><option value="night">Night</option></select></label><label>Description<input name="rate_description" maxlength="120" required></label><label>Hourly rate (ZAR)<input type="number" name="rate" min="0" step="0.01" required></label><button class="cnr-button">Save rate</button></form></section>';
}
function create_earnings_form(mysqli $conn): void { cnr_hr_earn_deduct_form($conn, 'earning'); }
function create_deductions_form(mysqli $conn): void { cnr_hr_earn_deduct_form($conn, 'deduction'); }
function cnr_hr_earn_deduct_form(mysqli $conn, string $type): void {
    $v=(int)($_SESSION['vendor_info']['id']??0);echo '<section class="cnr-form-card"><h3>Record '.cnr_h($type).'</h3><form method="post" action="/cnrbyte/vendors/module_action.run.php">'.cnr_csrf_field_local().'<input type="hidden" name="action" value="record_payroll_item"><input type="hidden" name="entry_type" value="'.cnr_h($type).'"><label>Staff member<select name="staff_id" required><option value="">Select staff</option>'.cnr_hr_staff_options($conn,$v).'</select></label><label>Description<select name="description" required><option value="">Select description</option>'.cnr_vendor_lookup_options($conn,$v,$type==='earning'?'earnings_type':'deductions_type').'</select></label><label>Amount (ZAR)<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Payroll period<input type="month" name="payroll_period" required></label><button class="cnr-button">Save '.cnr_h($type).'</button></form></section>';
}
function edit_shift_roster_form(mysqli $conn): void { show_shift_roster_table($conn); }
function edit_staff_roster_form(mysqli $conn): void { show_staff_roster_table($conn); }
function edit_staff_leave_form(mysqli $conn): void {
    $v=(int)($_SESSION['vendor_info']['id']??0);$stmt=$conn->prepare('SELECT l.id,l.leave_type,l.start_date,l.end_date,l.leave_status,l.reason,s.first_names,s.last_name FROM staff_leave l JOIN staff s ON s.id=l.staff_id AND s.vendor_id=l.vendor_id WHERE l.vendor_id=? ORDER BY l.created_at DESC LIMIT 100');$stmt->bind_param('i',$v);$stmt->execute();$res=$stmt->get_result();
    echo '<section class="cnr-form-card"><h3>Leave requests</h3><div class="cnr-table-wrap"><table><thead><tr><th>Staff</th><th>Type</th><th>Dates</th><th>Status</th><th>Reason</th></tr></thead><tbody>';while($r=$res->fetch_assoc())echo '<tr><td>'.cnr_h($r['first_names'].' '.$r['last_name']).'</td><td>'.cnr_h($r['leave_type']).'</td><td>'.cnr_h($r['start_date'].' to '.$r['end_date']).'</td><td>'.cnr_h($r['leave_status']).'</td><td>'.cnr_h($r['reason']).'</td></tr>';echo '</tbody></table></div></section>'; $stmt->close();
}
